// Pull FeedbackRecordIds out of the CSV and build one UPDATE statement.
const REQUIRED = 'FeedbackRecordId';
const MAX_IDS  = 20000;

const rows = $input.all();
const ctx  = $('Fetch Message + Attachments').first().json;
const messageId = ctx.id || ctx.messageId;
const subject   = ctx.subject || '';

const reject = (msg) => [{
  json: {
    ok: false,
    messageId,
    subject,
    replyBody:
      'Automated notice - feedback publication\n\n' +
      'STATUS: REJECTED - no database changes were made.\n\n' +
      msg + '\n\n' +
      'Expected: a CSV with a header column named exactly FeedbackRecordId,\n' +
      'one numeric id per row. Fix the file and resend.',
  },
}];

if (rows.length === 0) return reject('The CSV attachment contained no data rows.');

const headers = Object.keys(rows[0].json || {});
const col = headers.find(
  (h) => String(h).replace(/^\uFEFF/, '').trim().toLowerCase() === REQUIRED.toLowerCase()
);
if (!col) {
  return reject('Required column "' + REQUIRED + '" was not found. Columns detected: ' +
    (headers.join(', ') || '(none)') + '.');
}

const ids = [];
const seen = new Set();
const bad = [];

rows.forEach((r, i) => {
  const raw = (r.json || {})[col];
  const v = String(raw === undefined || raw === null ? '' : raw)
    .trim().replace(/^["']+|["']+$/g, '').trim();
  if (v === '') return;                                   // blank row
  if (!/^[0-9]{1,19}$/.test(v)) {                         // digits only - keeps the IN list safe
    bad.push('row ' + (i + 2) + ' = "' + v.slice(0, 40) + '"');
    return;
  }
  if (seen.has(v)) return;                                // duplicate
  seen.add(v);
  ids.push(v);
});

if (bad.length) {
  return reject(bad.length + ' value(s) in column "' + col + '" are not numeric FeedbackRecordIds. ' +
    'Nothing was updated. First offenders: ' + bad.slice(0, 10).join('; ') + '.');
}
if (ids.length === 0) return reject('Column "' + col + '" was present but contained no usable ids.');
if (ids.length > MAX_IDS) {
  return reject('The file contains ' + ids.length + ' ids, above the ' + MAX_IDS +
    ' safety limit. Split it and resend.');
}

const query =
  'SET NOCOUNT ON;\n' +
  'UPDATE dbo.FeedbackRecords\n' +
  '   SET IsPublished = 1\n' +
  ' WHERE (IsPublished IS NULL OR IsPublished <> 1)\n' +
  "   AND FeedbackRecordId IN ('" + ids.join("','") + "');\n" +
  'SELECT @@ROWCOUNT AS rowsUpdated;';

return [{ json: { ok: true, messageId, subject, idCount: ids.length, rowsInFile: rows.length, query } }];
